import sys; sys.path.insert(0, "Tools/prd_ledger/49")
from _lib import c, table, save
c(1, "header lines 1-8", "positioning", "Life Reset: 66 Day Habit (App Store ID 6478942469; subtitle 'Gamified Habit Tracker'; shipped as 'Rise: Life Reset in 66 Days' until mid-2025) by Savvy Tech Limited (bundle build.designand.rise) — 1,232 written reviews, 75 storefronts, 16 April 2024 – 7 September 2026, extracted 2026-09-08, analysed 12 September 2026; a Solo-Leveling-styled 66-day programme app sold behind a hard paywall after a long questionnaire", "gamified 66-day programme, hard paywall", "mixed", "1,232 reviews", "none", "corpus-level fact", "app-specific", [])
c(2, "§How to read this; §1.1-1.3, 1.5; §1.6", "data-caveat", "Method: all 1,232 records read individually in the original language (20+ languages) in date order in 21 chunks; hand-built 111-theme taxonomy in 10 families with explicit boundary rules (B01 price exists vs B02 price disclosed too late; E01 cannot add vs E02 cannot edit; F02 AI criticised vs F03 AI valued; E14 persona misfit vs F09 ideological; C03 refund refused vs I01 support unreachable); classified by working index and resolved deterministically to review_id; 11 integrity assertions (no duplicates, map covers exactly the source set, no unknown IDs, no unassigned, contiguous index, index and ID maps agree); 3,073 assignments, mean 2.49 per review; build refuses to write on any of 22 count-check disagreements; post-write verification of every cited ID; 13-field schema with no missing values; HTML entities (including double-escaped) unescaped for reading only; author never reported; no deduplication (three identical 'Good' reviews from three storefronts, effect < 0.25pp); themes under 10 reviews, all 106 payer reviews, all 40 scam-accusation reviews and all 27 contradictions re-read before publication; causation not established", "n/a", "n/a", "1,232 (100%)", "none", "method statement", "app-specific", ["13357929714","14389884342","14445102588"])
c(3, "§Eight warnings 1-3", "data-caveat", "The written corpus is not the rating corpus and the gap is enormous: 4.7★ from ~12,000 ratings vs 2.77★ written — a ~1.9-star divergence because a quarter of writers never got into the product; 'Do not read 2.77★ as the app's standing. Read it as the standing of the onboarding funnel'; 26.87% (331, mean 1.23★) never used the app — questionnaire, paywall, left; the corpus is young and back-loaded — 73.9% (910) written in 2025, the pre-scale era is 59 reviews", "n/a", "n/a", "331 never-used; 910 in 2025", "none", "corpus-level fact", "general", [])
c(4, "§Eight warnings 4-8", "data-caveat", "No verifiable price — reviewers quote $1.99/mo to $87, £2–£50, €12–€80, zł45–60, AU$17.98–80, CA$24.99–79.99, ¥3,000–4,500 across 29 months, and the listing's ten price points confirm the range is genuinely wide; payer identification (106, 8.60%) is a floor, not a conversion rate; payers average 1.92★ because satisfied payers rarely mention paying — the payer segment is an inventory of post-purchase failure modes; 28 reviews (2.27%) contain no product content; 27 (2.19%) contradict their own stars (J09), disclosed not re-scored", "ten price points", "n/a", "106 payers; 27 contradictions", "none", "corpus-level fact", "app-specific", [])
c(5, "§Executive summary opening", "insight", "A well-liked product with a broken front door: among reviewers who got inside, 167 (13.56%, 4.78★) report real behaviour change, 60 (4.87%, 4.55★) praise the level-up mechanic, 38 (3.08%, 4.87★) say the Solo Leveling framing is exactly what they wanted — but 43.67% of the corpus (538, mean 1.49★) attacks how the app is sold and supplies 74.6% of every 1–2★ review: 'The product is not the problem. The funnel is.'", "questionnaire → hard paywall funnel", "funnel anger vs product praise", "538 (43.67%) vs 436 (35.39%)", "mixed", "high", "general", [])
c(6, "§Executive summary 1", "anti-pattern", "One design decision explains most of the corpus — a 10–20 minute questionnaire in front of a hard paywall: B01 hard paywall, no free use 256 (20.78%, 1.31★), the largest theme of any kind; B02 onboarding completed before price disclosed 156 (12.66%, 1.15★), the lowest mean of any theme above 20; together 48.6% of all 1–2★; consistent across 75 storefronts and 20+ languages and almost always the same sentence — 'I spent 10–20 minutes answering personal questions, signed a pledge, and only then learned it costs money'; 37 (3.00%) add that the ad or listing said 'free', 20 (1.62%) frame it as data collection, 35 (2.84%) name the funnel devices — pledges, 'lock in' repetition, countdown discount — as manipulation", "long personal questionnaire + pledge, then hard paywall", "wasted time; feels tricked", "256 + 156; 48.6% of 1–2★", "negative", "high", "general", [])
c(7, "§Executive summary 2", "insight", "The free trial was tested both ways: 90 reviews (7.31%, 1.32★) ask for a trial; none existed for most of the corpus; from 24 January 2026 one appears — 11 reviews (B18) describe being charged immediately on signing up for a stated free trial, and trial-use mentions go from 0.20% to 2.85% — and introducing the trial did not reduce paywall anger, it converted it into billing anger: B01 rose from 17.24% to 34.96% across the boundary and 'advertised as free' from 2.13% to 6.50%; 'A trial that requires a card, auto-charges, and is hard to exit has bought the developer the reputational cost of a trial without the trust benefit'", "card-required auto-charging trial from 24 Jan 2026", "billing anger replaces paywall anger", "90 ask; 11 charged; B01 17.24% → 34.96%", "negative", "medium-high", "general", [])
c(8, "§Executive summary 3", "insight", "For people who pay the complaint is rigidity, not price: 80 (6.49%) cannot add their own tasks and 70 (5.68%) cannot edit or remove the generated programme — 9.43% and 15.09% among payers; running is the only cardio (20, plus 10 with injury, disability, asthma or nerve damage — 23 distinct); the wake-up window excludes night-shift workers (31, 23 identifying as shift workers); the weekly ramp reaches 90-minute lifts, 4-mile runs and 2 gallons of water for beginners (20); the day closes at 9pm regardless (10) — these sit at 3–4★, where E01 and E02 peak (17.65% and 14.41% of the 3★ band)", "auto-generated fixed programme", "people who wanted to stay", "80 + 70", "negative", "high", "general", [])
c(9, "§Executive summary 4", "must-never-break", "Paying customers report problems at nearly nine times the rate of everyone else and support does not catch them: 97 of 106 payers (91.5%) carry a complaint; reliability in 41.5% of payer reviews vs 13.4% of non-payers; progress reset or lost 14.15% of payers vs 2.92% globally, login failure 11.32% vs 1.30%, overcharged 8.49% vs 0.73%; 21 (1.70%, 1.43★) say support is unreachable — a dead button, a 404, a bouncing address, silence — 10 of them payers; 36 request refunds, 21 refused or ignored, 13 invoke a '66-day money-back guarantee' that several say did not materialise", "unreachable support; conditional guarantee", "paying customers left without recourse", "97 of 106 payers", "negative", "high", "general", [])
c(10, "§Executive summary 5", "timeline", "Reliability is episodic and datable: a launch-crash cluster in October 2024 (D01 37.5% of that window); a 22 May 2025 update that stopped the app opening (D01 + D13 37.8% of the following fortnight, users 20–39 days into a 66-day programme); a mid-June 2025 logout wave (D05 + D04 20.5%, 1.92★); an Aug–Sep 2025 signup-blocked cluster where the name field could not be scrolled past (15); a June 2026 crash-on-task-completion wave (32.1% of that month); crash on launch fell to zero in the most recent era while unspecified bugs rose to 7.9% and a new hero-mode bug theme appeared in 2026", "five incident windows", "n/a", "195 (15.83%)", "mixed", "high", "general", [])
c(11, "§Executive summary 6", "insight", "The AI objection is durable and aimed at craft, not function: 53 (4.30%, 1.85★) criticise AI-generated art, copy or book summaries — the only product-criticism theme rising in every era (0% → 4.4% → 4.0% → 5.5%), disproportionately Australian (10.34%) and American (4.66%); reviewers do not object to AI planning (4 praise it) but to paying a premium price for assets they read as uncommissioned — several would recommend the app if the art were commissioned", "AI art, copy and book summaries", "cheap for a premium price", "53 (4.30%)", "negative", "high", "general", [])
c(12, "§Executive summary 7", "positioning", "The Solo Leveling positioning is the growth engine and the expectation trap: 38 (3.08%, 4.87★) name the anime as why they love it; 15 (1.22%, 1.40★) as why they feel misled — expected an avatar, quests and penalties and found a checklist; 38 (3.08%, 1.68★) call it 'just a checklist'; 15 name Instagram or TikTok as where they found it; a character / hero mode shipped late 2025 and immediately generated its own bug theme — 'writing a cheque the product only partly cashes'", "anime-RPG marketing on Instagram / TikTok", "love it or feel misled", "38 vs 15 + 38", "mixed", "high", "general", [])
c(13, "§Executive summary 8", "audience", "Shift workers are a genuine, ignored, well-defined segment being turned away: 31 (2.52%, mean 3.42★ — notably higher than the corpus) cannot set a wake time outside a roughly 5am–10am window; 23 identify as night, graveyard or FIFO workers; their rating is high because they want the product, several saying so while uninstalling — 'the cheapest high-value fix in the report'", "wake time locked to ~5–10am", "want it, can't use it", "31 (3.42★)", "negative", "high", "general", [])
c(14, "§Executive summary strategic read", "do", "Priorities in order: disclose the price before the questionnaire, make the trial a real trial, let people edit their own programme, and answer paying customers when they write in — 40.18% of the corpus is already 4–5★ with unusually specific praise, so fixing the product is not the priority; three of the four are cheap", "n/a", "n/a", "four priorities", "none", "high", "general", [])
c(15, "§1.4 date range table", "timeline", "Yearly: 2024 (from 16 Apr) 52 reviews, mean 2.58, 55.8% 1–2★ · 2025 910 (73.9%), 2.76, 50.7% · 2026 (to 7 Sep) 270, 2.87, 50.4%; monthly volume 1–13 through 2024, stepping up February 2025 and peaking at 146 in August 2025, coinciding with the Instagram / TikTok campaign 15 reviews name; the 1–2★ share is stable at ~50% while the 5★ share rises from 19.2% (2024) to 37.0% (2026) — 'the negative half is not shrinking; the positive half is getting more positive'; body median 152 characters, 98 ≤ 20", "paid social acquisition ramp", "n/a", "peak 146 in Aug 2025", "mixed", "high", "app-specific", ["11164609337","14519880651","11825234292","13073292592"])
c(16, "§1.6 limitations", "data-caveat", "Selection bias unusually severe (the ~10% who write over-represent paywall bounces — 'a complete, articulable experience that takes 20 minutes to acquire and 30 seconds to write up'); the honest product denominator is ~901; payer self-identification skews toward people whose payment became salient because something went wrong; the most recent era (E4, from 1 Dec 2025) is 290 reviews, so hero-mode bugs (5) and trial billing (11) are genuine but small; only five storefronts clear 50 (US, CA, DE, GB, AU — 73.78%) and the US is 47.00%; prices, plan names and features changed during the window (rename, character mode, trial); borderline calls concentrate in B01 vs B02, E01 vs E02, and D18 vs specific reliability themes", "n/a", "n/a", "n/a", "none", "method statement", "app-specific", [])
c(17, "§2.1 feature inventory table", "data-caveat", table("## 2.1 Feature inventory"), "n/a", "n/a", "n/a", "none", "corpus-level fact", "app-specific", ["13073292592","12181485638","13329009131","12999503079","12917102928","12576463690","13110133783","12900289560","13654164676","12315868340","13072368493","12936813410","13037385252","13592233963","13596312321","14195130483","13780831362","12366219056","12955163393","13189323301","14116238467","13406494249","12888691060","13406026400","12979102442","14508328179","13229989580","12937610877","12764415874","12883609029","12865447391","13324975532","13838798854","14181754070","13900765197","12917164876","13046112649","12471607720","12604750095","14519880651","13013314943","13018958577","13072200651","13029589554","13339495032","13118822768","12945514746","12963409255","12969618294","12634875883","12921714751","12944427920","12992530011","13045702582","13346302196","14203716713"])
c(18, "§2.1 programme and game mechanics", "feature", "A fixed-length 66-day programme auto-generated from an onboarding questionnaire, 5–8 preset daily tasks (wake early, water, run, workout, read, meditate, journal, no social media, cold shower, pray, no-fap) marked done / partial / skipped by swipe, difficulty escalating weekly; XP, an overall rating and category stats (Strength, Wisdom, Focus, Discipline) — the single most-praised mechanic (60); optional hard mode that resets to day 1 with penalty tasks on a miss (13); a character / hero mode with equipment, loot and battles from late 2025; collectible achievement art and motivational cards; day N / 66 counter plus streak and XP multiplier, a frequent source of bugs (11)", "66-day auto-generated programme with RPG stats, hard mode and hero mode", "levelling is the most-praised mechanic", "60 XP praise; 13 hard mode", "positive", "high", "general", [])
c(19, "§2.1 bundled tools", "feature", "Bundled tools: condensed non-fiction book summaries (23, mean 4.09 — liked, English-only), guided meditation (failures and synthetic-sounding audio reported), an app / screen blocker consistently praised ('a godsend'), a Pomodoro focus timer, a workout tracker with a fixed ~15-exercise list and no custom entries, a calorie tracker (2026 only, settings not persisting), a journal (added 2025), a home-screen widget often blank or stuck on day 1 (8), a daily recap that fires at a fixed ~9pm and closes the day's scoring (10), an official Discord with an active developer (17, 4.65), referral codes, iPhone / iPad / Mac builds with iPad and Mac layouts broken (15), German added ~May 2025 while books and meditations stay English, an under-18 / student free programme not visible on the listing (3), and a marketed 66-day money-back guarantee reportedly requiring 66 logged days at ≥ 50% completion (13)", "all-in-one self-improvement bundle", "tools praised; widget, iPad / Mac and meditation broken", "see counts", "mixed", "high", "general", [])
c(20, "§2.2 free / paid table", "monetization", "Free: the onboarding questionnaire, the personalised 'analysis' result and the paywall — nothing else (256 say so); paid: everything — quests, XP, streaks, hard mode, books, meditation, blocker, trackers, widgets, customisation — no usable free tier at any point in 29 months; trial absent, then present from 24 January 2026 with 11 charged at signup or trial end without effective warning; monthly and annual plans — 15 object to the structure: a 66-day programme sold as an annual subscription, monthly priced so two months exceed the year, or annual-only at checkout; refunds attempted via the App Store, 21 of 36 refused or ignored; unclear whether the student / under-18 free programme is official", "hard paywall; monthly + annual; trial from Jan 2026", "structure objections", "256 / 15 / 36", "negative", "high", "general", [])
c(21, "§2.3 external sources", "data-caveat", "Listing (12 Sep 2026): Savvy Tech Limited, Health & Fitness, 9+, free with IAP, version 6.5.3, 4.7★ from ~12,000 ratings; ten IAP price points — $12.99, $17.99, $28.99, $34.99, $39.99, $49.99, $59.99 as 'Life Reset (Full Access)' plus $12.99, $28.99, $49.99 under the legacy 'Rise' name — confirming the rename and that the wide reported range is real; the listing states core features require subscription and onboarding is free, matching the corpus exactly", "ten price points under two product names", "n/a", "listing facts", "none", "corpus-level fact", "app-specific", [])
